338→export default function PricingPage() {
339→  const { subscription } = useLoaderData<typeof loader>();
340→  const fetcher = useFetcher<typeof action>();
341→  const shopify = useAppBridge();
342→
343→  const [isAnnual, setIsAnnual] = useState(
344→    subscription.billingInterval === "annual",
345→  );
346→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
347→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
348→
349→  const data = fetcher.data;
350→  const isFetching = fetcher.state !== "idle";
351→
352→  // Redirect to Shopify billing confirmation page
353→  useEffect(() => {
354→    if (data && "confirmationUrl" in data && data.confirmationUrl) {
355→      window.open(data.confirmationUrl as string, "_top");
356→    }
357→  }, [data]);
358→
359→  // Toast notifications + clear loading state
360→  useEffect(() => {
361→    if (!isFetching) setLoadingPlan(null);
362→    if (data && "message" in data && data.message) {
363→      shopify.toast.show(data.message as string);
364→    }
365→    if (data && "error" in data && data.error) {
366→      shopify.toast.show(data.error as string, { isError: true });
367→    }
368→  }, [data, isFetching, shopify]);
369→
370→  const handleSubscribe = useCallback(
371→    (planName: string) => {
372→      setLoadingPlan(planName);
373→      const fd = new FormData();
374→      fd.set("intent", "subscribe");
375→      fd.set("plan", planName);
376→      fetcher.submit(fd, { method: "POST" });
377→    },
378→    [fetcher],
379→  );
380→
381→  const handleConfirmCancel = useCallback(() => {
382→    setCancelModalOpen(false);
383→    setLoadingPlan("cancel");
384→    const fd = new FormData();
385→    fd.set("intent", "cancel");
386→    fetcher.submit(fd, { method: "POST" });
387→  }, [fetcher]);
388→
389→  const currentTier = subscription.planTier;
390→  const currentPlanName =
391→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
392→
393→  return (
394→    <Page
395→      title="Pricing"
396→      subtitle="Choose the plan that's right for your store"
397→      backAction={{ url: "/app" }}
398→    >
399→      <Box paddingBlockEnd="1600">
400→      <Layout>
401→        <Layout.Section>
402→          <BlockStack gap="600">
403→
404→            {/* Current plan status */}
405→            {currentTier === "free" ? (
406→              <Banner
407→                tone="info"
408→                title="You're on the Free plan"
409→                action={{
410→                  content: "Upgrade to Pro",
411→                  onAction: () => {
412→                    const plan = isAnnual
413→                      ? PLANS_DATA.pro.shopifyPlanAnnual
414→                      : PLANS_DATA.pro.shopifyPlanMonthly;
415→                    if (plan) handleSubscribe(plan);
416→                  },
417→                }}
418→              >
419→                <Text as="p" variant="bodyMd">
420→                  You have up to 25 allowed zip codes and basic widget access.
421→                  Upgrade to unlock unlimited zip codes, blocked areas, delivery
422→                  rules, and more.
423→                </Text>
424→              </Banner>
425→            ) : (
426→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
427→                <InlineStack gap="200" blockAlign="center">
428→                  <Badge tone="success">Active</Badge>
429→                  <Text as="p" variant="bodyMd">
430→                    {currentTier === "ultimate"
431→                      ? "You have full access to all features including VIP support and API access."
432→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
433→                  </Text>
434→                </InlineStack>
435→              </Banner>
436→            )}
437→
438→            {/* Action feedback banners */}
439→            {data && "error" in data && data.error && (
440→              <Banner tone="critical">{String(data.error)}</Banner>
441→            )}
